insert into public.articles(id,data,published,provenance) values ('evaluate-ai','{"id":"evaluate-ai","slug":"evaluate-ai","name":"How to evaluate an AI solution before you buy","description":"A practical guide to evidence, integration, and the questions worth asking.","body":"Start with an outcome you can measure. Define a small, representative evaluation using your own data. Ask suppliers to explain retention, access controls, model limitations, and total operating cost.\n\nRecord what you observe rather than relying on a score alone. Compare integration effort, human oversight, and ongoing support. Agree on acceptance criteria before a pilot begins.\n\nA solution stack is a starting hypothesis. Test each connection, verify licensing, and assign responsibility for every handoff.","category":"BUYER GUIDE","date":"2026-09-01","provenance":"demo"}'::jsonb,true,'demo') on conflict(id) do update set data=excluded.data;
insert into public.articles(id,data,published,provenance) values ('connected-operations','{"id":"connected-operations","slug":"connected-operations","name":"From isolated tools to connected operations","description":"What to consider when building your first technology stack.","body":"Map the workflow from input to outcome. Identify where data enters, who reviews decisions, and where results are delivered.\n\nDefine a contract for each integration: input format, authentication, failure handling, and ownership. Start with one workflow, measure it, and expand deliberately.","category":"STACK DESIGN","date":"2026-09-02","provenance":"demo"}'::jsonb,true,'demo') on conflict(id) do update set data=excluded.data;
insert into public.articles(id,data,published,provenance) values ('robotics-pilot','{"id":"robotics-pilot","slug":"robotics-pilot","name":"Planning your first robotics pilot","description":"Explore deployment environments, safety reviews, and partner selection.","body":"Observe the process in its real environment. Document variability, human interactions, constraints, and maintenance needs.\n\nBring in a qualified implementation partner to assess feasibility and relevant safety requirements. Use a controlled pilot with clear success criteria before scaling.","category":"FIELD NOTES","date":"2026-09-03","provenance":"demo"}'::jsonb,true,'demo') on conflict(id) do update set data=excluded.data;
